def get_sequence(n, k):
    seq = list(range(1, n + 1))
    for _ in range(k):
        new_seq = []
        for i in range(len(seq) - 1):
            new_seq.append(seq[i])
            new_seq.append(seq[i] + seq[i+1])
        new_seq.append(seq[-1])
        seq = new_seq
    return seq

for n in [2, 3]:
    for k in range(5):
        seq = get_sequence(n, k)
        print(f"n={n}, k={k}: {seq}")

def get_coefficients(n, k):
    # coeffs[k][j] is a list of coefficients for a_1, ..., a_n
    # coeffs[k][j][i] is the coefficient of a_{i+1}
    coeffs = []
    # k=0
    current_coeffs = [[0]*n for _ in range(n)]
    for i in range(n):
        current_coeffs[i][i] = 1
    coeffs.append(current_coeffs)

    for _ in range(k):
        new_coeffs = []
        # first element
        new_coeffs.append(current_coeffs[0][:])
        # intermediate elements
        for j in range(len(current_coeffs) - 1):
            # x_{j} + x_{j+1}
            c_sum = [current_coeffs[j][i] + current_coeffs[j+1][i] for i in range(n)]
            new_coeffs.append(c_sum)
            # x_{j+1}
            new_coeffs.append(current_coeffs[j+1][:])
        # last element
        new_coeffs.append(current_coeffs[-1][:])
        coeffs.append(new_coeffs)
    return coeffs

for n in [2, 3]:
    for k in range(5):
        coeffs = get_coefficients(n, k)
        print(f"n={n}, k={k}:")
        for j, c in enumerate(coeffs[-1]):
            print(f"  x_{j}: {c}")

